# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİNLER ARASI KARŞILAŞTIRMA VE KİŞİLİK ÖZELLİKLERİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Karakter Karşılaştırması (Bölüm 2)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Gazi Mustafa Kemal Atatürk:</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#334155">• Alçakgönüllü, halkla iç içe, şefkatli</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#334155">• Eğitime önem veren, vefalı ve cömert</text>\n  <text x="180" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Sığırtmaç Mustafa:</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" fill="#334155">• Tokgözlü, dürüst, onurlu ve çalışkan</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">• Emeğinin karşılığı olmayan parayı kabul etmeyen</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Ortak Yön: Dürüstlük, vatan sevgisi ve samimiyet</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Metin Türleri Arası Karşılaştırma</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">• Öyküleyici Metin (Anı / Hikâye):</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#78350f">Kişi, yer, zaman ve olay örgüsü vardır;</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" fill="#78350f">serim - düğüm - çözüm bölümlerinden oluşur.</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">• Şiir ve Bilgilendirici Metin:</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#78350f">Şiirde dize, dörtlük, kafiye ve coşkulu dil;</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#78350f">bilgilendirici metinde giriş-gelişme-sonuç vardır.</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Aynı tema farklı metin türleriyle işlenebilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZCÜKTE YAPI: İSİM VE FİİL KÖKLERİ İLE YAPIM EKLERİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İsim Kökü ve Fiil Kökü Ayrımı</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">1. İsim (Ad) Kökü (-mak / -mek ALMAZ):</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#166534">Varlık, kavram ve duyguları karşılar:</text>\n  <text x="180" y="140" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">yol, göz, su, vatan, çift, taş, tuz</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">2. Fiil (Eylem) Kökü (-mak / -mek ALIR):</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#166534">İş, oluş ve hareket bildirir:</text>\n  <text x="180" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">yaz-, sev-, bil-, gör-, bak-, yürü-</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Yapım Ekleri ve Türemiş Sözcükler</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">• Yapım Eki (-lı, -sız, -lık, -cı, -gi, -ıcı):</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#6b21a8">Eklendiği kökün anlamını (bazen türünü) değiştirir.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">• göz + lük ➔ gözlük (Türemiş Sözcük)</text>\n  <text x="520" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">• çift + çi ➔ çiftçi  |  tuz + suz ➔ tuzsuz</text>\n  <text x="520" y="190" text-anchor="middle" font-size="12" font-weight="bold" fill="#4c1d95">• bil- + gi ➔ bilgi  |  sev- + gi + li ➔ sevgili</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#475569">Yapım eki almamış sözcüklere «basit sözcük» denir (yollar).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAĞLANTI İFADELERİ, SÖZ SANATLARI VE YAZIM-NOKTALAMA</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">Bağlantı ve Geçiş İfadeleri</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">• Düşünceyi Değiştirenler:</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#0c4a6e">ama, fakat, lakin, ancak, oysa</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">• Neden-Sonuç / Destekleyen:</text>\n  <text x="125" y="160" text-anchor="middle" font-size="11" fill="#0c4a6e">çünkü, bu nedenle, ayrıca, üstelik</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">• Özetleyen İfadeler:</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" fill="#0c4a6e">kısacası, özetle, sonuç olarak</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">Söz Sanatları</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• Benzetme (Teşbih):</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#9d174d">«Güneş gibi parlayan gözler»</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• Kişileştirme (Teşhis):</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#9d174d">«Ağaçlar neşeyle selam verdi»</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• Konuşturma ve Abartma:</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" fill="#9d174d">İntak (konuşturma), Mübalağa</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Yazım ve Noktalama</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Kişi adlarından önce ve sonra</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#14532d">gelen unvanlar büyük yazılır:</text>\n  <text x="575" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Gazi Mustafa Kemal Paşa</text>\n  <text x="575" y="160" text-anchor="middle" font-size="11" fill="#14532d">• Karşılıklı konuşmalarda</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11" fill="#14532d">iki nokta (:), uzun çizgi (—)</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11" fill="#14532d">ve tırnak işareti (« ») kullanılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
